import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Data-Input-and-Output.md","filePath":"manual-en/Data-Input-and-Output.md","lastUpdated":1785684581000}'),n={name:"manual-en/Data-Input-and-Output.md"};function s(o,t,i,u,l,p){return e(),d("div",null,[...t[0]||(t[0]=[r('<h2 id="_8-data-input-and-output" tabindex="-1">8 Data Input and Output <a class="header-anchor" href="#_8-data-input-and-output" aria-label="Permalink to &quot;8 Data Input and Output&quot;">​</a></h2><p>Data are the focus of the PSPP language. Each datum belongs to a <em>case</em> (also called an <em>observation</em>). Each case represents an individual or “experimental unit”. For example, in the results of a survey, the names of the respondents, their sex, age, etc. and their responses are all data and the data pertaining to single respondent is a case. This chapter examines the PSPP commands for defining variables and reading and writing data. There are alternative commands to read data from predefined sources such as system files or databases (See <a href="./GET">GET DATA</a>.)</p><blockquote><p><strong>Note:</strong> These commands tell PSPP how to read data, but the data will not actually be read until a procedure is executed.</p></blockquote><table tabindex="0"><thead><tr><th>• BEGIN DATA</th><th></th><th>Embed data within a syntax file.</th></tr></thead><tbody><tr><td>• CLOSE FILE HANDLE</td><td></td><td>Close a file handle.</td></tr><tr><td>• DATAFILE ATTRIBUTE</td><td></td><td>Set custom attributes on data files.</td></tr><tr><td>• DATASET</td><td></td><td>Manage multiple datasets.</td></tr><tr><td>• DATA LIST</td><td></td><td>Fundamental data reading command.</td></tr><tr><td>• END CASE</td><td></td><td>Output the current case.</td></tr><tr><td>• END FILE</td><td></td><td>Terminate the current input program.</td></tr><tr><td>• FILE HANDLE</td><td></td><td>Support for special file formats.</td></tr><tr><td>• INPUT PROGRAM</td><td></td><td>Support for complex input programs.</td></tr><tr><td>• LIST</td><td></td><td>List cases in the active dataset.</td></tr><tr><td>• NEW FILE</td><td></td><td>Clear the active dataset.</td></tr><tr><td>• PRINT</td><td></td><td>Display values in print formats.</td></tr><tr><td>• PRINT EJECT</td><td></td><td>Eject the current page then print.</td></tr><tr><td>• PRINT SPACE</td><td></td><td>Print blank lines.</td></tr><tr><td>• REREAD</td><td></td><td>Take another look at the previous input line.</td></tr><tr><td>• WRITE</td><td></td><td>Display values in write formats.</td></tr></tbody></table>',4)])])}const m=a(n,[["render",s]]);export{h as __pageData,m as default};
